  5169          def->magic[3] = 'M';
  5170          def->major_version = 0; // Indicator to write file def later.
  5171          def->minor_version = 0;
  5172          memset(def->file_id, 0, 20);
  5173          strncpy(def->file_id, filename, 20);
  5174
  5175          fd->version = major_version * 256 + minor_version;
  5176          cram_init_tables(fd);
